const sumOrgUnitSpendSince = `-- name: SumOrgUnitSpendSince :one
SELECT COALESCE(SUM(u.cost_usd_ticks), 0)::bigint FROM task_usage u
JOIN agent_task_queue q ON q.id = u.task_id
WHERE q.issue_id IN (
    SELECT DISTINCT f.issue_id FROM org_flow f
    WHERE f.structure_id = $1 AND f.unit_id = $2 AND f.kind = 'routing' AND f.issue_id IS NOT NULL
) AND q.created_at >= $3::timestamptz
`

type SumOrgUnitSpendSinceParams struct {
	StructureID pgtype.UUID        `json:"structure_id"`
	UnitID      string             `json:"unit_id"`
	Since       pgtype.Timestamptz `json:"since"`
}

// What a unit's routed issues cost: usage of the runs on issues the unit was routed.
func (q *Queries) SumOrgUnitSpendSince(ctx context.Context, arg SumOrgUnitSpendSinceParams) (int64, error) {
	row := q.db.QueryRow(ctx, sumOrgUnitSpendSince, arg.StructureID, arg.UnitID, arg.Since)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}

